import { type Href, router } from 'expo-router';

// Typed routes are generated by the dev server, so screens added in this
// batch (/search, /tag/[tag], /notifications, /follow-requests) are missing
// from the generated file until it runs again. Paths are built as strings in
// one place instead of casting at every call site.
export function go(path: string) {
  router.push(path as Href);
}

export const tagPath = (tag: string) => `/tag/${encodeURIComponent(tag.replace(/^#+/, ''))}`;
export const userPath = (id: string) => `/user/${encodeURIComponent(id)}`;
export const videoPath = (id: string) => `/video/${encodeURIComponent(id)}`;
export const soundPath = (id: string) => `/sound/${encodeURIComponent(id)}`;

// Many rows store the mp4 itself as the thumbnail, which an image view
// cannot draw; those tiles show the plain placeholder instead.
export const isImageUrl = (url: string | null | undefined): url is string =>
  !!url && !/\.(mp4|mov|webm|m4v)(\?|$)/i.test(url);
